/* PROTOTYPE: seven native screen studies, three structures each. No API, storage or real mutations.
   Question: which clarity problems need shared components, and which need a different flow? */
const params = new URLSearchParams(location.search);
const validScreens = ['adventure','planner','settings','voice','account','recovery','family','audit','components'];
let screen = validScreens.includes(params.get('screen')) ? params.get('screen') : 'adventure';
let variant = ['A','B','C'].includes(params.get('variant')) ? params.get('variant') : 'B';
let language = params.get('lang') === 'en' ? 'en' : 'fi';
let mode = params.get('mode') === 'focus' ? 'focus' : 'compare';
let scenario = ['normal','offline','error'].includes(params.get('state')) ? params.get('state') : 'normal';
let large = params.get('text') === 'large';
let memory = {A:{}, B:{}, C:{}};
const t = (en,fi) => language === 'fi' ? fi : en;
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 arrow:'<path d="m14 6-6 6 6 6"/>',chevron:'<path d="m9 6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',
 settings:'<path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',
 voice:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M9 22h6"/>',
 account:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7"/>',
 recovery:'<path d="M4 5v6h6M4 11a8 8 0 1 1 1 7"/><path d="M12 8v5l3 2"/>',adventure:'<path d="M5 22V2M5 4h12l3 4-3 4H5M5 14h9l3 3-3 3H5"/>',
 planner:'<path d="m4 16 12-12 4 4L8 20l-5 1zM13 7l4 4"/>',audit:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>',
 components:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 17.5h7M17.5 14v7"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01"/>',
 language:'<path d="M3 5h12M9 3v2M6 5c0 5 4 9 8 10M12 5c0 5-4 9-8 10M14 21l4-11 4 11M16 17h4"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wifi:'<path d="M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0M9 16a4 4 0 0 1 6 0M12 20h.01"/>',
 list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',
 logout:'<path d="M9 3H4v18h5M13 7l5 5-5 5M8 12h13"/>'
};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.chevron}</svg>`;
const names=()=>({adventure:t('No adventure yet','Ei vielä seikkailua'),planner:t('Plan an adventure','Suunnittele seikkailu'),settings:t('Settings','Asetukset'),voice:t('Voice & recordings','Puhe ja tallenteet'),account:t('Account','Tili'),recovery:t('Saved work & recovery','Tallennetut työt'),family:t('Family setup','Perheen käyttöönotto'),audit:t('Whole-app audit','Koko sovelluksen arvio'),components:t('Shared components','Yhteiset komponentit')});
const concepts=()=>({A:{title:t('Consistent controls','Yhtenäiset painikkeet'),body:t('Keep the familiar page. Fix hierarchy, labels and button shapes.','Tuttu sivu säilyy. Selkeämmät otsikot, tekstit ja painikkeet.')},B:{title:t('Task first','Tärkein ensin'),body:t('Show the next useful action. Reveal the rest when it matters.','Näytä seuraava hyödyllinen toiminto. Muut tiedot avataan tarvittaessa.')},C:{title:t('One decision at a time','Yksi valinta kerrallaan'),body:t('Break complex setup into small, explicit choices.','Jaa monimutkainen käyttöönotto pieniksi valinnoiksi.')}});
const findings={
 adventure:['The empty view explains the model, then offers an outlined planner and a plain-text Refresh. There is no visual invitation to begin.','Tyhjä näkymä selittää toimintamallia. Suunnittelupainike jää sivuosaan ja Päivitä näyttää tekstiltä.'],
 planner:['A large illustration pushes the form down. Several separate hints compete with the actual goal, and suggested ideas look like prose.','Suuri kuva työntää lomaketta alas. Ohjetekstit kilpailevat tavoitteen kanssa ja ehdotetut ideat näyttävät leipätekstiltä.'],
 settings:['Centered text links look like headings. Language and appearance explanations take more space than the settings themselves.','Keskitetyt tekstilinkit näyttävät otsikoilta. Selitykset vievät enemmän tilaa kuin itse asetukset.'],
 voice:['Provider names lead the page. Setup and history are text buttons; privacy, limits and licenses compete at the same level.','Palveluntarjoajien nimet hallitsevat sivua. Käyttöönotto ja historia ovat tekstipainikkeita. Tietosuoja ja tekniset rajat kilpailevat huomiosta.'],
 account:['Sign-in appears even when already signed in. Recovery, reminders and diagnostics lack clear navigation affordances.','Kirjautumispainike näkyy myös kirjautuneelle. Palautus, muistutukset ja yhteystiedot eivät näytä selvästi avattavilta.'],
 recovery:['Format names and device registration leak into a task about keeping your work. Several destructive actions share one generic confirmation.','Tiedostomuodot ja laitteen rekisteröinti sekoittuvat omien töiden säilyttämiseen. Eri poistotoiminnoilla on yhteinen vahvistusteksti.'],
 family:['The newer welcome flow has clear buttons. The older household screen duplicates it and exposes forms, refresh and member administration together.','Uuden aloituksen painikkeet ovat selkeitä. Vanha perhenäkymä toistaa saman polun ja yhdistää lomakkeet, päivityksen ja jäsenhallinnan.']
};
function btn(label,action,kind='primary',ico='',disabled=false,extra=''){return `<button class="btn ${kind}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${ico?icon(ico):''}${label}</button>`}
function row(title,subtitle,ico,action){return `<button class="row" data-action="${action}">${icon(ico)}<span><strong>${title}</strong>${subtitle?`<small>${subtitle}</small>`:''}</span>${icon('chevron')}</button>`}
function disclosure(title,body,open=false){return `<details class="disclosure" ${open?'open':''}><summary>${title}${icon('chevron')}</summary><div class="details-body">${body}</div></details>`}
function toggle(label,description,key,value){return `<div class="setting"><span><strong>${label}</strong>${description?`<small>${description}</small>`:''}</span><button class="switch" role="switch" aria-label="${label}" aria-checked="${value}" data-action="toggle:${key}"></button></div>`}
function choice(title,desc,action,selected=false){return `<button class="choice ${selected?'selected':''}" data-action="${action}" aria-pressed="${selected}"><i class="radio" aria-hidden="true"></i><span><strong>${title}</strong>${desc?`<small>${desc}</small>`:''}</span></button>`}
function field(label,key,value='',placeholder='',type='text'){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea data-field="${key}" placeholder="${placeholder}" maxlength="1000">${esc(value)}</textarea>`:`<input data-field="${key}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${type==='number'?'min="1" max="1440"':''}>`}${type==='number'?`<small class="hint">${t('Use 1 to 1,440 minutes, or leave empty.','Anna 1–1 440 minuuttia tai jätä tyhjäksi.')}</small>`:''}</label>`}
function steps(n,total){return `<div class="step-label">${t('Step','Vaihe')} ${n} / ${total}</div><div class="step-line" aria-hidden="true">${Array.from({length:total},(_,i)=>`<i class="${i<n?'done':''}"></i>`).join('')}</div>`}
function notice(s){return s.message?`<div class="inline-note" role="status">${s.message}</div>`:''}
const offline=()=>scenario==='offline';
const validMinutes=s=>!s.minutes || (Number.isInteger(Number(s.minutes)) && Number(s.minutes)>=1 && Number(s.minutes)<=1440);
function connection(){return offline()?`<div class="callout warning">${t('You are offline. You can keep working on saved tasks. Connect to start or change a shared adventure.','Ei verkkoyhteyttä. Voit jatkaa tallennettuja tehtäviä. Seikkailun aloittamiseen tai muuttamiseen tarvitaan yhteys.')}</div>`:''}
function appbar(title,back='nav:settings'){return `<header class="appbar"><button class="icon-button" data-action="${back}" aria-label="${t('Back','Takaisin')}">${icon('arrow')}</button><strong>${title}</strong><img src="assets/bun.svg" alt=""></header>`}
function art(name='dojo_garden',cls=''){return `<img class="art ${cls}" src="assets/${name}.webp" alt="">`}
function privacy(){return `<p>${t('Automatic speech sends audio to Microsoft Azure. On-device speech keeps audio on this phone. Optional AI suggestions send transcript text online separately.','Automaattinen puheentunnistus lähettää äänen Microsoft Azureen. Laitteen puheentunnistus pitää äänen puhelimessa. Valinnainen tekoälyapu lähettää puheesta tehdyn tekstin erikseen verkkoon.')}</p>`}
function voiceInstall(s){return `<p>${t('Download about 465 MiB. Installation needs about 1.5 GiB of free space, plus space for an existing model. Use Wi-Fi if possible.','Lataus on noin 465 MiB. Asennus tarvitsee noin 1,5 GiB vapaata tilaa mahdollisen vanhan mallin lisäksi. Käytä mieluiten Wi-Fiä.')}</p>${btn(s.installed?t('Installed in this demo','Asennettu esikatselussa'):t('Download offline speech','Lataa puheentunnistus'), 'install','primary','download',offline()||s.installed)}${offline()?`<p>${t('Connect to download. You can still type.','Yhdistä verkkoon lataamista varten. Voit silti kirjoittaa.')}</p>`:''}`}
function voiceOptions(s){return toggle(t('AI task suggestions','Tekoälyn tehtäväehdotukset'),t('Sends transcript text online. You review it before saving.','Lähettää puheesta tehdyn tekstin verkkoon. Tarkistat ehdotukset ennen tallennusta.'),'analysis',s.analysis!==false)+toggle(t('Keep recordings for 7 days','Säilytä tallenteet 7 päivää'),s.keep?t('New recordings stay on this phone.','Uudet tallenteet säilyvät tällä puhelimella.'):t('Off. Audio is deleted after transcription or failure.','Pois. Ääni poistetaan tekstiksi muuttamisen tai epäonnistumisen jälkeen.'),'keep',!!s.keep)}
function voice(v,s){
 if(s.page==='install')return appbar(t('Offline speech','Puheentunnistus ilman verkkoa'),'back')+`<div class="content"><h2>${t('Speak without a connection','Sanele myös ilman verkkoa')}</h2><p class="body">${t('Download Parakeet once. Your audio stays on this phone.','Lataa Parakeet kerran. Ääni pysyy tällä puhelimella.')}</p>${voiceInstall(s)}${disclosure(t('Model and licenses','Malli ja lisenssit'),'<p>Parakeet TDT 0.6b v3 · NVIDIA · CC BY 4.0. sherpa-onnx · Apache 2.0. ONNX Runtime · MIT.</p>')}${btn(t('Back to voice settings','Takaisin puheasetuksiin'),'back','secondary')}</div>`;
 if(v==='C')return appbar(t('Voice settings','Puheasetukset'),'nav:settings')+`<div class="content">${steps(s.step===2?2:1,2)}${s.step===2?`<h2>${t('What should Bun keep?','Mitä Bun säilyttää?')}</h2>${voiceOptions(s)}${disclosure(t('Storage and privacy','Tallennus ja tietosuoja'),privacy()+`<p>${t('Retained audio expires after 7 days, up to 20 recordings or 256 MiB. Draft text does not expire with audio.','Säilytettävä ääni poistuu 7 päivän kuluttua. Enintään 20 tallennetta tai 256 MiB. Tekstiluonnokset eivät vanhene äänen mukana.')}</p>`)}<div class="actions">${btn(t('Finish voice setup','Valmis'),'voice-finish')}${btn(t('Previous step','Edellinen vaihe'),'step:1','secondary')}</div>`:`<h2>${t('Where should speech become text?','Missä puhe muutetaan tekstiksi?')}</h2>${choice(t('Automatic','Automaattisesti'),t('Microsoft Azure online. Installed Parakeet offline.','Microsoft Azure verkossa. Asennettu Parakeet ilman verkkoa.'),'local:false',!s.local)}${choice(t('Only on this phone','Vain tällä puhelimella'),t('No audio upload. One download to get started.','Ääntä ei lähetetä verkkoon. Vaatii kertaluonteisen latauksen.'),'local:true',s.local)}${s.local&&!s.installed?`<div class="callout">${voiceInstall(s)}</div>`:''}<div class="actions">${btn(t('Continue','Jatka'),'step:2','primary','',s.local&&!s.installed)}</div>${row(t('Drafts and recordings','Luonnokset ja tallenteet'),t('Open saved voice work','Avaa tallennetut sanelut'),'file','voice-history')}`}</div>`;
 return appbar(t('Voice and recordings','Puhe ja tallenteet'))+`<div class="content">${v==='A'?`<h2>${t('Speech to text','Puhe tekstiksi')}</h2>${choice(t('Automatic','Automaattinen'),t('Microsoft Azure online, Parakeet offline.','Microsoft Azure verkossa, Parakeet ilman verkkoa.'),'local:false',!s.local)}${choice(t('On this phone','Tällä puhelimella'),t('Audio stays on this device.','Ääni pysyy tällä laitteella.'),'local:true',s.local)}<p class="hint">${t('Automatic mode sends online audio to Microsoft Azure.','Automaattinen tila lähettää verkossa käsiteltävän äänen Microsoft Azureen.')}</p>${btn(t('Set up offline speech','Ota offline-sanelu käyttöön'),'page:install','secondary','download')}`:`<h2>${t('Speak, then check the text','Sanele ja tarkista teksti')}</h2>${row(t('Speech to text','Puhe tekstiksi'),s.local?t('On this phone','Tällä puhelimella'):t('Automatic','Automaattinen'),'voice','voice-mode')}<p class="hint">${s.local?t('Audio stays here. Download offline speech below if needed.','Ääni pysyy täällä. Lataa tarvittaessa puheentunnistus alta.'):t('Online audio goes to Microsoft Azure. Offline speech needs a download.','Verkossa ääni lähetetään Microsoft Azureen. Offline-sanelu vaatii latauksen.')}</p>`}${voiceOptions(s)}<div class="rows">${v==='B'?row(t('Offline speech','Sanelu ilman verkkoa'),s.installed?t('Installed','Asennettu'):t('Not downloaded','Ei ladattu'),'download','page:install'):''}${row(t('Drafts and recordings','Luonnokset ja tallenteet'),t('No saved recordings','Ei tallennettuja äänitteitä'),'file','voice-history')}</div>${disclosure(t('Privacy and storage details','Tietosuoja ja tallennustila'),privacy()+`<p>${t('If kept, new recordings expire after 7 days, up to 20 recordings or 256 MiB. Draft text stays available.','Säilytettävät uudet äänitteet vanhenevat 7 päivässä. Enintään 20 tallennetta tai 256 MiB. Tekstiluonnokset säilyvät.')}</p>`)}</div>`;
}
function settings(v,s){
 const prefs=toggle(t('Small action animations','Pienet toimintoanimaatiot'),'', 'motion',s.motion!==false)+toggle(t('Bun garden','Bunin puutarha'),'', 'garden',s.garden!==false);
 const lang=row(t('App language','Sovelluksen kieli'),t('English','Suomi'),'language','language-choice');
 if(v==='C')return appbar(t('Settings','Asetukset'),'home')+`<div class="content"><h2>${t('What would you like to change?','Mitä haluat muuttaa?')}</h2><div class="rows">${row(t('How I add tasks','Tehtävien lisääminen'),t('Voice, AI suggestions and recordings','Puhe, tekoälyehdotukset ja tallenteet'),'voice','nav:voice')}${row(t('Who I share with','Kenen kanssa jaan tehtäviä'),t('Family and account','Perhe ja tili'),'home','nav:account')}${row(t('How Bun Do looks','Sovelluksen ulkoasu'),t('Language, garden and motion','Kieli, puutarha ja animaatiot'),'settings','settings-appearance')}${row(t('Find saved work','Etsi tallennettuja töitä'),t('Copy or recover tasks','Kopioi tai palauta tehtäviä'),'recovery','nav:recovery')}</div></div>`;
 return appbar(t('Settings','Asetukset'),'home')+`<div class="content">${v==='A'?`<div class="rows">${row(t('Family setup','Perheen käyttöönotto'),'', 'home','nav:family')}${row(t('Voice and recordings','Puhe ja tallenteet'),'', 'voice','nav:voice')}${row(t('Account','Tili'),'', 'account','nav:account')}</div><h3>${t('Appearance','Ulkoasu')}</h3>${prefs}<h3>${t('App language','Sovelluksen kieli')}</h3>${['system','fi','en'].map(k=>choice(k==='system'?t('Use device language','Laitteen kieli'):k==='fi'?'Suomi':'English','',`pref-lang:${k}`,(s.prefLang||'system')===k)).join('')}`:`<div class="rows">${row(t('Family and account','Perhe ja tili'),t('Sharing, members and sign-in','Jakaminen, jäsenet ja kirjautuminen'),'home','nav:account')}${row(t('Voice and recordings','Puhe ja tallenteet'),t('Speech, AI suggestions and saved audio','Puhe, tekoälyehdotukset ja tallenteet'),'voice','nav:voice')}${row(t('Reminders','Muistutukset'),t('When to remind me','Milloin haluan muistutuksen'),'clock','reminders')}${row(t('Saved work and recovery','Tallennetut työt ja palautus'),t('Copy tasks or export a backup','Kopioi tehtäviä tai vie varmuuskopio'),'recovery','nav:recovery')}</div><h3>${t('This app','Tämä sovellus')}</h3>${lang}${prefs}`}${disclosure(t('About these settings','Tietoa asetuksista'),`<p>${t('Language does not translate task content. Device reduced-motion settings override animations. Large text leaves more room for tasks by hiding the garden.','Kielen vaihtaminen ei käännä tehtävien sisältöä. Laitteen vähennetyn liikkeen asetus ohittaa animaatiot. Suuri teksti jättää enemmän tilaa tehtäville piilottamalla puutarhan.')}</p>`)}</div>`;
}
function family(v,s){
 if(s.page==='create'||s.page==='join')return appbar(s.page==='create'?t('Create a family','Luo perhe'):t('Join your family','Liity perheeseen'),'back')+`<div class="content">${v==='C'?steps(2,2):''}<h2>${s.page==='create'?t('A place for your family','Paikka perheellesi'):t('Come on in','Tervetuloa mukaan')}</h2>${field(t('Your name','Nimesi'),'name',s.name||'',t('What should we call you?','Millä nimellä sinua kutsutaan?'))}${field(s.page==='create'?t('Family name','Perheen nimi'):t('Invitation link','Kutsulinkki'),s.page==='create'?'familyName':'invite',(s.page==='create'?s.familyName:s.invite)||'',s.page==='create'?t('Our home','Meidän koti'):'https://…')}<p class="hint">${s.page==='join'?t('The person who invited you will check your code before you join.','Kutsun lähettäjä tarkistaa koodisi ennen liittymistä.'):t('Use a Microsoft account to share tasks. Local tasks stay separate.','Jaa tehtäviä Microsoft-tilillä. Paikalliset tehtävät pysyvät erillään.')}</p><div class="actions">${btn(t('Continue with Microsoft','Jatka Microsoft-tilillä'),'mock-signin','primary','',offline())}</div>${offline()?`<p class="hint">${t('Connect to continue. Your fields stay here.','Yhdistä verkkoon jatkaaksesi. Syöttämäsi tiedot säilyvät tässä.')}</p>`:''}</div>`;
 return appbar(t('Family setup','Perheen käyttöönotto'),'nav:settings')+`<div class="content">${v==='C'?steps(1,2):art('welcome_gate','welcome')}<h2>${t('Everyday things, together','Arjen asiat yhdessä')}</h2>${v==='A'?`<p class="body">${t('Make a shared task list, or join someone who invited you.','Luo yhteinen tehtävälista tai liity kutsulla mukaan.')}</p><div class="actions">${btn(t('Create a family','Luo perhe'),'page:create','primary','plus')}${btn(t('I have an invitation','Minulla on kutsu'),'page:join','secondary')}</div>`:`<p class="body">${t('How would you like to begin?','Miten haluat aloittaa?')}</p>${choice(t('Start a family list','Luo perheen lista'),t('Create a home for your shared tasks.','Luo paikka yhteisille tehtäville.'),'family:create',(s.familyChoice||'create')==='create')}${choice(t('Join with an invitation','Liity kutsulla'),t('Someone has already invited me.','Olen jo saanut kutsun.'),'family:join',s.familyChoice==='join')}<div class="actions">${btn(t('Continue','Jatka'),'family-continue')}</div>`}${row(t('Keep using this phone only','Jatka vain tällä puhelimella'),t('You can set up a family later.','Voit ottaa perheen käyttöön myöhemmin.'),'list','local-tasks')}${disclosure(t('What happens to my existing tasks?','Mitä nykyisille tehtävilleni tapahtuu?'),`<p>${t('They stay on this phone. After joining a family, choose which tasks to copy into the shared list.','Ne pysyvät tällä puhelimella. Liittymisen jälkeen voit valita, mitkä tehtävät kopioit yhteiseen listaan.')}</p>`)}</div>`;
}
function account(v,s){
 const identity=`<h2>${t('Your family','Perheesi')}</h2><p>${t('Our home','Meidän koti')}</p><p class="hint">${t('Signed in with Microsoft','Kirjautunut Microsoft-tilillä')}</p>`;
 const details=disclosure(t('Connection details','Yhteyden tiedot'),`<p>${t('Check your connection if shared tasks are not updating.','Tarkista yhteys, jos yhteiset tehtävät eivät päivity.')}</p>${btn(t('Check connection','Tarkista yhteys'),'check-connection','secondary')}`);
 if(v==='C')return appbar(t('Family and account','Perhe ja tili'))+`<div class="content">${identity}<h3>${t('What do you need?','Mitä haluat tehdä?')}</h3><div class="rows">${row(t('Manage my family','Hallitse perhettäni'),t('Invite someone or manage members','Kutsu mukaan tai hallitse jäseniä'),'home','members')}${row(t('Use another account','Käytä toista tiliä'),t('Review saved work first','Tarkista tallennetut työt ensin'),'account','switch-account')}${row(t('Recover my work','Palauta työni'),t('Find text saved on this phone','Etsi puhelimelle tallennetut tekstit'),'recovery','nav:recovery')}${row(t('Fix a connection problem','Selvitä yhteysongelma'),'', 'wifi','check-connection')}</div>${btn(t('Sign out','Kirjaudu ulos'),'signout','secondary')}${details}</div>`;
 return appbar(t('Family and account','Perhe ja tili'))+`<div class="content">${identity}${v==='B'?`<div class="actions">${btn(t('Invite someone','Kutsu mukaan'),'invite','primary','plus')}</div>`:''}<div class="rows">${row(t('Family members','Perheen jäsenet'),t('Manage sharing','Hallitse jakamista'),'home','members')}${v==='A'?row(t('Reminders','Muistutukset'),'', 'clock','reminders'):''}${row(t('Saved work and recovery','Tallennetut työt ja palautus'),'', 'recovery','nav:recovery')}${row(t('Use another account','Käytä toista tiliä'),'', 'account','switch-account')}</div>${details}<div class="actions">${btn(t('Sign out','Kirjaudu ulos'),'signout','secondary','logout')}</div>${disclosure(t('Remove data from this phone','Poista tiedot tältä puhelimelta'),`<p>${t('Delete this account’s local data and sign out. Export anything you want to keep first. Shared tasks are not deleted.','Poistaa tämän tilin paikalliset tiedot ja kirjaa ulos. Vie ensin kaikki säilytettävät tiedot. Yhteisiä tehtäviä ei poisteta.')}</p>${btn(t('Review and delete local data','Tarkista ja poista paikalliset tiedot'),'delete-local','danger')}`)}</div>`;
}
function exportOptions(){return `<p class="hint">${t('These files contain private task text. Choose where you save them. Recordings are exported separately.','Tiedostot sisältävät yksityisiä tehtävätekstejä. Valitse tallennuspaikka huolella. Äänitteet viedään erikseen.')}</p><div class="actions">${btn(t('Save a recovery file','Tallenna palautustiedosto'),'export-json','primary','download')}${btn(t('Save a readable text copy','Tallenna luettava tekstikopio'),'export-text','secondary','file')}</div>${disclosure(t('Which file do I need?','Kumman tiedoston tarvitsen?'),`<p>${t('The recovery file is JSON for importing back into Bun Do. The text copy is for reading in another app. Originals stay unchanged.','Palautustiedosto on JSON-muodossa, ja sen voi tuoda takaisin Bun Doon. Tekstikopion voi lukea toisessa sovelluksessa. Alkuperäiset säilyvät ennallaan.')}</p>`)}`}
function savedItems(s){return ['Buy oat milk','Book the bike service'].map((en,i)=>`<label class="checklist-option"><input type="checkbox" data-item="${i}" ${s.excluded?.includes(i)?'':'checked'}><span>${t(en,['Osta kauramaitoa','Varaa pyörähuolto'][i])}<small class="hint" style="display:block">${t('Saved on this phone','Tallennettu tälle puhelimelle')}</small></span></label>`).join('')}
function recovery(v,s){
 if(s.page==='export')return appbar(t('Save a copy','Tallenna kopio'),'back')+`<div class="content">${v==='C'?steps(2,2):''}<h2>${t('Keep a copy of your work','Säilytä kopio töistäsi')}</h2>${exportOptions()}</div>`;
 if(s.page==='review')return appbar(t('Review saved text','Tarkista tallennetut tekstit'),'back')+`<div class="content"><h2>${t('Choose what to keep','Valitse säilytettävät')}</h2><p class="hint">${t('Copies become new tasks in your local inbox. Nothing is sent to your family yet. Originals stay unchanged.','Kopioista tulee uusia paikallisia tehtäviä. Mitään ei vielä lähetetä perheelle. Alkuperäiset säilyvät ennallaan.')}</p>${savedItems(s)}<div class="actions">${btn(t('Copy selected tasks','Kopioi valitut tehtävät'),'copy-selected','primary','',s.excluded?.length===2)}</div></div>`;
 return appbar(t('Saved work and recovery','Tallennetut työt ja palautus'),'nav:account')+`<div class="content">${v==='C'?steps(1,2):''}<h2>${v==='C'?t('What would you like to recover?','Mitä haluat palauttaa?'):t('Your saved work','Tallennetut työsi')}</h2>${scenario==='error'?`<div class="callout warning">${t('Some saved work could not be opened. Sign in with the same account to check what can be recovered.','Osaa tallennetuista töistä ei voitu avata. Kirjaudu samalla tilillä tarkistaaksesi, mitä voidaan palauttaa.')}${btn(t('Sign in again','Kirjaudu uudelleen'),'mock-signin','secondary')}</div>`:''}${v==='A'?`<p class="body">${t('2 text records on this phone. You choose what to copy or export.','Tällä puhelimella on 2 tallennettua tekstiä. Valitset itse kopioitavat ja vietävät tiedot.')}</p>${btn(t('Review saved text','Tarkista tallennetut tekstit'),'page:review','primary')}${exportOptions()}${row(t('Import a recovery file','Tuo palautustiedosto'),'', 'file','import')}`:v==='B'?`<p class="body">${t('2 tasks are saved on this phone. Review them before copying.','Tällä puhelimella on 2 tallennettua tehtävää. Tarkista ne ennen kopiointia.')}</p><div class="review-item"><strong>${t('Buy oat milk','Osta kauramaitoa')}</strong><small>${t('Local task','Paikallinen tehtävä')}</small></div><div class="review-item"><strong>${t('Book the bike service','Varaa pyörähuolto')}</strong><small>${t('Local task','Paikallinen tehtävä')}</small></div><div class="actions">${btn(t('Review and copy tasks','Tarkista ja kopioi tehtävät'),'page:review')}</div><div class="rows">${row(t('Save a backup copy','Tallenna varmuuskopio'),'', 'download','page:export')}${row(t('Import a recovery file','Tuo palautustiedosto'),'', 'file','import')}${row(t('Recordings','Äänitteet'),t('Open voice settings','Avaa puheasetukset'),'voice','nav:voice')}</div>`:`<div class="rows">${row(t('Tasks saved on this phone','Puhelimelle tallennetut tehtävät'),t('Review 2 saved texts','Tarkista 2 tallennettua tekstiä'),'list','page:review')}${row(t('A backup file','Varmuuskopiotiedosto'),t('Choose a Bun Do recovery file','Valitse Bun Don palautustiedosto'),'file','import')}${row(t('A recording','Äänite'),t('Open saved voice work','Avaa tallennetut sanelut'),'voice','nav:voice')}</div>${btn(t('I want to save a backup','Haluan tallentaa varmuuskopion'),'page:export','secondary')}`}${disclosure(t('How recovery works','Miten palautus toimii?'),`<p>${t('Recovered text becomes new local tasks. It does not restore old claims, completions or deletions. Copying to the family queue is a separate choice.','Palautetusta tekstistä tulee uusia paikallisia tehtäviä. Vanhoja varauksia, valmistumisia tai poistoja ei palauteta. Kopiointi perheen listalle valitaan erikseen.')}</p>`)}</div>`;
}
function adventure(v,s){
 if(s.page==='queue')return appbar(t('Family tasks','Perheen tehtävät'),'back')+`<div class="content">${art('dojo_garden')}<h2>${t('What needs doing?','Mitä pitäisi tehdä?')}</h2><p class="body">${t('Start with one everyday thing.','Aloita yhdestä arjen asiasta.')}</p>${field(t('Task title','Tehtävän nimi'),'task',s.task||'',t('Buy oat milk','Osta kauramaitoa'))}<div class="actions">${btn(t('Add a task','Lisää tehtävä'),'add-task')}${btn(t('Speak a task','Sanele tehtävä'),'demo-record','secondary','voice')}</div></div>`;
 if(s.page==='suggestion')return appbar(t('Adventure preview','Seikkailun esikatselu'),'back')+`<div class="content">${art()}<h2>${t('A calmer kitchen','Keittiö kuntoon')}</h2><p class="hint">${t('Demo suggestion · 3 existing tasks','Esimerkkiehdotus · 3 olemassa olevaa tehtävää')}</p>${['Clear the table','Put the dishes away','Wipe the counters'].map((x,i)=>`<div class="review-item"><strong>${t(x,['Tyhjennä pöytä','Laita astiat paikoilleen','Pyyhi tasot'][i])}</strong></div>`).join('')}<p class="hint">${t('Starts for your family. Tasks stay unclaimed.','Alkaa koko perheelle. Tehtäviä ei varata kenellekään.')}</p>${btn(t('Start our adventure','Aloita seikkailumme'),'start-adventure','primary','',offline())}</div>`;
 const help=disclosure(t('How adventures work','Miten seikkailut toimivat?'),`<p>${t('Bun can group at least three eligible main tasks from your family queue. Or describe a goal and review a plan with new tasks. Nothing is added until you approve.','Bun voi yhdistää vähintään kolme sopivaa päätehtävää perheen listalta. Voit myös kuvata tavoitteen ja tarkistaa suunnitelman uusine tehtävineen. Mitään ei lisätä ilman hyväksyntääsi.')}</p>`);
 const error=scenario==='error'?`<div class="callout error">${t('Suggestions could not be loaded. Your tasks are unchanged.','Ehdotuksia ei voitu ladata. Tehtäväsi eivät muuttuneet.')}${btn(t('Try again','Yritä uudelleen'),'retry-adventures','secondary','',offline())}</div>`:'';
 const title=v==='A'?t('No adventure yet','Ei vielä seikkailua'):v==='B'?t('Make a little room for an adventure','Aloitetaan pieni seikkailu'):t('Where should we begin?','Mistä aloitetaan?');
 return appbar(t('Our adventure','Seikkailumme'),'home')+`<div class="content">${v==='B'?art():v==='A'?'<img class="bun-mark" src="assets/bun.svg" alt="">':''}<h2>${title}</h2>${connection()}${error}${v==='C'?`<p class="body">${t('Pick something to work on together.','Valitkaa jotain yhdessä tehtävää.')}</p>${choice(t('Plan something new','Suunnittele jotain uutta'),t('Describe a goal. Bun suggests the tasks.','Kuvaa tavoite. Bun ehdottaa tehtävät.'),'adventure-choice:new',(s.adventureChoice||'new')==='new')}${choice(t('Use our existing tasks','Käytä nykyisiä tehtäviä'),t('Add tasks to the queue first.','Lisää ensin tehtäviä listalle.'),'adventure-choice:existing',s.adventureChoice==='existing')}<div class="actions">${btn(s.adventureChoice==='existing'?t('Go to tasks','Siirry tehtäviin'):t('Plan an adventure','Suunnittele seikkailu'),'adventure-next','primary','',false)}</div>`:`<p class="body">${v==='A'?t('Add a few tasks to your family list, or plan something new together.','Lisää tehtäviä perheen listalle tai suunnittele yhdessä jotain uutta.'):t('Tell Bun what you want to get done. You choose which tasks to add.','Kerro Bunille, mitä haluat saada aikaan. Valitset itse lisättävät tehtävät.')}</p><div class="actions">${btn(t('Plan an adventure','Suunnittele seikkailu'),'nav:planner','primary','plus')}${btn(t('Add tasks to our list','Lisää tehtäviä listalle'),'page:queue','secondary','list')}</div>`}${help}</div>`;
}
function plannerReview(v,s){const tasks=[t('Clear the table','Tyhjennä pöytä'),t('Put the dishes away','Laita astiat paikoilleen'),t('Wipe the counters','Pyyhi tasot')];return appbar(t('Review adventure','Tarkista seikkailu'),'back')+`<div class="content"><h2>${t('Make it your own','Muokkaa omannäköiseksi')}</h2><p class="hint">${t('Sample plan, not AI output. Edit or leave out any task.','Esimerkkisuunnitelma, ei tekoälyn tuotos. Muokkaa tehtäviä tai jätä niitä pois.')}</p>${field(t('Adventure name','Seikkailun nimi'),'planName',s.planName??s.goal??t('A calmer kitchen','Keittiö kuntoon'))}${tasks.map((x,i)=>`<div class="review-item">${field(t('New task','Uusi tehtävä')+` ${i+1}`,'review'+i,s['review'+i]??x)}${toggle(t('Include this task','Lisää tämä tehtävä'),'',`include${i}`,s['include'+i]!==false)}</div>`).join('')}<p class="hint">${t('Adds the selected tasks to your family queue and starts the shared adventure when they have synced.','Lisää valitut tehtävät perheen listalle. Yhteinen seikkailu alkaa, kun tehtävät on synkronoitu.')}</p><div class="actions">${btn(t('Add tasks and start','Lisää tehtävät ja aloita'),'approve-plan','primary','',offline())}${btn(t('Back to my idea','Takaisin ideaan'),'back','secondary')}</div>${connection()}</div>`}
function planner(v,s){
 if(s.page==='review')return plannerReview(v,s);
 const goal=field(t('What would you like to get done?','Mitä haluat saada aikaan?'),'goal',s.goal||'',t('For example, get the kitchen ready for the weekend','Esimerkiksi keittiö kuntoon viikonlopuksi'),'textarea');
 const ideas=s.ideas?`<div class="rows">${['A calmer kitchen','Make room in the hallway','Get ready for the weekend'].map((en,i)=>row(t(en,['Keittiö kuntoon','Eteiseen lisää tilaa','Valmistaudu viikonloppuun'][i]),'', 'plus',`idea:${i}`)).join('')}</div>`:'';
 const time= v==='A'?field(t('Minutes available, optional','Aikaa minuutteina, valinnainen'),'minutes',s.minutes||'','','number'):`<h3>${t('How much time?','Paljonko aikaa?')}</h3><div class="chip-row">${['15','30','60',''].map(x=>`<button class="chip ${String(s.minutes||'')===x?'selected':''}" data-action="minutes:${x}" aria-pressed="${String(s.minutes||'')===x}">${x?x+' min':t('No limit','Ei aikarajaa')}</button>`).join('')}</div>${disclosure(t('Choose another time','Valitse muu aika'),field(t('Minutes, optional','Minuuttia, valinnainen'),'minutes',s.minutes||'','','number'))}`;
 const generation=btn(t('Preview a plan','Esikatsele suunnitelma'),'generate','primary','',offline()||!s.goal?.trim()||!validMinutes(s),'data-generate');
 return appbar(t('Plan an adventure','Suunnittele seikkailu'),'nav:adventure')+`<div class="content">${v==='C'?steps(s.step===2?2:1,2):v==='A'?art():''}<h2>${v==='C'&&s.step===2?t('Make it fit your day','Sovita suunnitelma päivääsi'):t('What shall we tackle?','Mihin tartutaan?')}</h2>${connection()}${scenario==='error'?`<div class="callout error">${t('The plan could not be prepared. Your idea is still here. Try again when connected.','Suunnitelmaa ei voitu tehdä. Ideasi on edelleen tässä. Yritä uudelleen, kun yhteys toimii.')}</div>`:''}${v==='C'&&s.step===2?`<p>${esc(s.goal)}</p>${time}`:`${goal}<div class="actions">${btn(t('Speak your idea','Sanele ideasi'),'demo-record','secondary','voice')}${btn(t('Suggest ideas for us','Ehdota meille ideoita'),'ideas','tonal','spark',offline())}</div><p class="hint">${t('AI ideas use your family tasks and recent task history.','Tekoälyn ideat perustuvat perheen tehtäviin ja viimeaikaiseen tehtävähistoriaan.')}</p>${ideas}${v==='C'?'':time}`}${v==='C'&&s.step!==2?`<div class="actions">${btn(t('Continue','Jatka'),'planner-next','primary','',!s.goal?.trim(),'data-continue')}</div>`:`<div class="actions">${generation}</div><p class="hint">${t('Prepared online. You review everything before tasks are added.','Tehdään verkossa. Tarkistat kaiken ennen tehtävien lisäämistä.')}</p>`}${v==='C'&&s.step===2?btn(t('Previous step','Edellinen vaihe'),'step:1','secondary'):''}</div>`;
}
const auditRows=[
 ['Settings','First batch','Centered Family setup and Voice links look like headings. Use leading icons, left-aligned labels and trailing chevrons. Move account into the same navigation grammar.','InboxApp.kt'],
 ['Voice settings & model installation','First batch','Lead with speech behavior, not “Speech model”. Keep audio destination visible. Move provider/version/license detail behind an explicit disclosure. Download must remain an obvious button.','VoiceSettings.kt'],
 ['Account & sign-out','First batch','Replace repeat sign-in with “Use another account”. Separate family actions, recovery and diagnostics. Each sign-out/delete operation needs its own accurate confirmation.','AccountScreen.kt'],
 ['Saved work & recovery','First batch','Lead with the saved text and its destination. Label JSON as a recovery file, keep format detail available, and explain that imports create new local tasks. Never hide unresolved work.','AccountScreen.kt; SharedWorkspaceScreen.kt; LegacyRecordingsSection.kt'],
 ['Family setup & membership','First batch','Welcome has clearer buttons than the older Household screen. Reuse its create/join path. Keep matching-code approval, invitation expiry and destructive membership warnings intact.','WelcomeScreen.kt; WelcomeRoute.kt; HouseholdScreen.kt'],
 ['Adventure without an active adventure','First batch','Give the empty state one useful filled action. Distinguish no eligible tasks, disconnected, expired suggestions and failed loading. Routine Refresh should not be the main way forward.','SharedAdventureScreen.kt'],
 ['Guided adventure planning','First batch','Reduce the image before the form. Make AI ideas visibly selectable. Keep voice and typing peers. Preview and family-wide approval remain separate steps.','GuidedAdventureScreen.kt'],
 ['Active adventure, preview & editing','Next batch','“Remove reference”, “phase name” and “main tasks complete” expose the internal structure. Say “Remove from adventure”, “Step name” and “3 of 5 tasks done”. Keep actual task titles distinct from story names.','SharedAdventureScreen.kt'],
 ['Together & empty statistics','Next batch','Zero is normal. Seven empty bars plus streak/counting paragraphs are not useful first-run content. Put the first useful action before counting rules; keep those rules in “How counts work”.','SharedProgressScreen.kt'],
 ['Bun journey, before and after start','Next batch','“First completions at this stop” is implementation language. Show “2 of 5 tasks to the next stop”. Explain repeat completion and sync rules on request, while preserving the explicit online start.','SharedJourneyScreen.kt'],
 ['Reminders & permission denial','Next batch','“Date-only reminder time” and HH:mm syntax describe data. Use “When no time is set” with a native time picker. Show blocked notifications as a warning only when reminders are wanted.','ReminderSettingsSection.kt'],
 ['Repeats','Next batch','“Save repeat online” embeds transport in the button. Prefer “Save repeat”; explain a missing connection beside the disabled action. Keep future-task and stop/delete consequences at the relevant decision.','SharedRepeatControls.kt'],
 ['Task details & scheduling','Next batch','Main task actions already use buttons. Secondary actions and date presets vary between text, outlined buttons and chips. Standardize by purpose, not globally replacing every TextButton. Keep creator/change attribution discoverable.','SharedTaskControls.kt; SharedTaskMetadata.kt; TaskDateFields.kt'],
 ['Checklist, AI split & cleanup','Next batch','Use “Add steps”, “Suggest steps” and “Review suggestion” consistently. Limits belong beside invalid input, not every empty editor. Keep comparison and explicit approval.','SharedChecklist.kt; SharedCleanupControls.kt'],
 ['Voice recording & review','Small copy pass','The focused flow is worth keeping. “Microsoft MAI online, Parakeet offline” is too much in the recording sheet. Use “Online speech” with settings for details. Preserve Stop, typing fallback and editable review.','VoiceSheet.kt'],
 ['Typed capture & local task editor','Keep structure','Title first, save, draft safety and optional detail are appropriate. Make validation contextual; avoid repeated character-limit help when input is valid.','InboxApp.kt'],
 ['Queue, empty queue & queue filters','Keep structure','Compact queue, clear Type/Speak actions and short empty-state copy match the intended language. Reorder help can be disclosed after the first use. Do not turn the queue into cards.','SharedQueue.kt; InboxApp.kt'],
 ['Sync conflict, access loss & retained edits','Keep warnings; refine actions','These are not clutter to remove. Preserve saved text, shared state and explicit reapply/copy/dismiss. Show actionable consequences, with technical diagnostics on request.','SharedWorkspaceScreen.kt'],
 ['Activity & event details','Keep structure','The latest compact event rows already use a consistent icon, actor/action text and explicit details. Keep unavailable-task states distinct from the empty feed.','SharedActivityScreen.kt'],
 ['World scene, trail & navigation','Keep structure','The approved artwork, quiet signpost and three main destinations provide continuity. The study reuses those assets rather than creating another visual language.','HouseholdScene.kt; BunAdventureTrail.kt; HouseholdWorld.kt; SharedHouseholdNavigation.kt']
];
function audit(){return `<section class="notes-panel" lang="en"><h2>Clarity audit, September 17</h2><p>I would fix the shared control vocabulary first. Settings and advanced screens drift from the compact, illustrated task queue. The adventure empty state also needs a different hierarchy, not just a stronger border.</p><h3>What was checked</h3><p>All Android UI source files and their English/Finnish string resources at commit <code>68ecedb8</code>. Live emulator inspection covered the local queue, Settings, voice settings and Account. Existing native captures were checked for guided planning and adventure states. The table is a source-and-design review, not a claim that every live state or TalkBack path was exercised.</p><h3>What stays</h3><p>Evergreen #245B48, paper #F8F9F4, Android system type, Material controls, the approved rabbit, the dojo artwork, flat task rows and light-only presentation. Keep privacy, unsynced work, family-wide changes and deletion consequences visible where the decision happens.</p><table class="audit-table"><thead><tr><th>Screen or flow</th><th>Priority</th><th>Finding and direction</th></tr></thead><tbody>${auditRows.map(r=>`<tr><td>${r[0]}<code>${r[3]}</code></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table><h3>Native evidence</h3><p>These are evidence of the current visual language, not the proposed variants. Capture state can differ from the demo data. The guided-planning capture predates the current AI-ideas controls; current source owns that behavior.</p><div class="evidence"><figure><img src="assets/current-settings.png" alt="Current native settings with centered text links and long explanatory text" loading="lazy"><figcaption>Settings, live emulator, September 17. Normal text links read as headings.</figcaption></figure><figure><img src="assets/current-voice.png" alt="Native voice settings with provider names and long storage explanations" loading="lazy"><figcaption>Voice settings, live emulator, September 17. Provider and storage language is prominent.</figcaption></figure><figure><img src="assets/prior-planner.png" alt="Prior native guided planner with large art above the goal form" loading="lazy"><figcaption>Guided planning, retained native evidence from the adventure follow-up. Large art displaces the form.</figcaption></figure></div><h3>Read this study as a proposal</h3><p>A mainly changes controls and copy. B changes information hierarchy and navigation. C introduces guided setup steps. Navigation changes, the system time picker and contextual notices need native work and fresh behavioral/accessibility verification. No proposal is silently added to DESIGN.md.</p></section>`}
function components(){return `<section class="notes-panel" lang="en"><h2>One vocabulary, across the app</h2><p>These are proposed shared Compose patterns, not a new theme. Use Material components underneath. The first implementation should remove variation in affordances, not add wrappers around every line of text.</p><h3>Actions have a boundary</h3><p>A filled button is the main action. An outlined button is an alternative. A tonal button offers optional assistance. Keep text buttons for quiet dismissals and conventional app-bar actions, not the only way into settings or recovery.</p><div class="component-demo">${btn(t('Plan an adventure','Suunnittele seikkailu'),'nav:planner','primary','plus')}${btn(t('Add tasks to our list','Lisää tehtäviä listalle'),'nav:adventure','secondary','list')}${btn(t('Suggest ideas for us','Ehdota meille ideoita'),'nav:planner','tonal','spark')}</div><h3>Navigation is a row</h3><p>Leading icon, label, optional current value and trailing chevron. The entire row is a 48 dp or larger target. Left-align every settings destination. A chevron means “open”, never “save”.</p><div class="component-demo">${row(t('Voice and recordings','Puhe ja tallenteet'),t('Automatic speech','Automaattinen puheentunnistus'),'voice','nav:voice')}${row(t('Saved work and recovery','Tallennetut työt ja palautus'),t('Review text on this phone','Tarkista puhelimelle tallennetut tekstit'),'recovery','nav:recovery')}</div><h3>Detail is available, not mandatory</h3><p>Disclosure rows expose explanations without competing with the action. Do not hide data destination, active failures or destructive consequences. A collapsed section needs an obvious chevron.</p><div class="component-demo">${disclosure(t('How adventures work','Miten seikkailut toimivat?'),t('At least three eligible main tasks make an adventure suggestion. You can also plan new tasks and review them before adding.','Seikkailuehdotus tarvitsee vähintään kolme sopivaa päätehtävää. Voit myös suunnitella uusia tehtäviä ja tarkistaa ne ennen lisäämistä.'))}</div><h3>Empty state is a next step</h3><p>One heading, one useful sentence, one main action and at most one alternative. A first visit is not an error. Loading, offline, “nothing matches” and failed requests need different messages.</p><h3>Suggested native building blocks</h3><p><code>SettingsNavigationRow</code>, <code>SettingToggleRow</code>, <code>HelpDisclosure</code> and <code>ActionableEmptyState</code>. Reuse Material Button/OutlinedButton/FilledTonalButton directly. Keep confirmation copy beside the real operation rather than inventing a generic destructive-action component.</p><h3>Copy to retire</h3><table class="audit-table"><thead><tr><th>Current</th><th>Proposed</th></tr></thead><tbody><tr><td>Set up Parakeet</td><td>Set up offline speech · Ota offline-sanelu käyttöön</td></tr><tr><td>Verify token refresh</td><td>Check connection · Tarkista yhteys</td></tr><tr><td>Remove reference</td><td>Remove from adventure · Poista seikkailusta</td></tr><tr><td>Export JSON, part 1</td><td>Save a recovery file · Tallenna palautustiedosto</td></tr><tr><td>Date-only reminder time</td><td>When no time is set · Kun aikaa ei ole asetettu</td></tr><tr><td>Continue selected action</td><td>Name the exact action: Sign out, Delete local data, Remove member.</td></tr></tbody></table></section>`}
function auxiliary(v,s){
 const title=s.auxTitle||t('Details','Lisätiedot');
 return appbar(title,'close-aux')+`<div class="content">${s.auxBody||''}${s.confirm?`<div class="actions">${btn(s.confirm.label,'confirm-demo',s.confirm.danger?'danger':'primary')}${btn(t('Cancel','Peruuta'),'close-aux','secondary')}</div>`:btn(t('Back','Takaisin'),'close-aux','secondary')}</div>`;
}
function renderPhone(v){const s=memory[v],renderers={settings,voice,account,recovery,adventure,planner,family};return (s.aux?auxiliary(v,s):renderers[screen](v,s)).replace('</header>',`</header>${notice(s)}`)}
const tradeoffs={
 settings:{A:'Mostly components and shorter copy. Language still takes vertical space.',B:'Recommended. One settings list, with reminders and account in the same place. Changes navigation.',C:'Easy first scan, but grouping by intent adds a tap for familiar settings.'},
 voice:{A:'Keeps every preference visible. The clearest low-risk native refactor.',B:'Recommended. Everyday settings first; offline download gets its own page.',C:'Useful for initial setup, slower for returning users. Needs a summary entry afterward.'},
 account:{A:'Closest to today. Explicit navigation, no redundant sign-in, safer separation of deletion.',B:'Recommended. Family identity and invite first; recovery and account switching stay discoverable.',C:'Good for troubleshooting. Intent labels are longer and add a step.'},
 recovery:{A:'Makes formats understandable but still presents several choices at once.',B:'Recommended. Saved text leads. Review makes the local destination explicit.',C:'Better for an occasional recovery task, but less efficient for frequent exports.'},
 adventure:{A:'Lowest-risk fix. Clear primary action and a short explanation.',B:'Recommended. Existing dojo art makes the invitation feel part of Bun Do.',C:'A real fork between existing tasks and new plans. An extra tap when the queue is empty.'},
 planner:{A:'Keeps the existing form and art. Clear buttons, but still the tallest layout.',B:'Recommended. The idea is first, with optional time presets and an obvious preview.',C:'One question at a time. Less dense on a phone, but slower to revise goal and time together.'},
 family:{A:'Recommended baseline. Reuse the newer welcome flow rather than redesigning it.',B:'Choice and Continue separate the decision from the action, at the cost of one tap.',C:'Makes the steps explicit, useful if the account transition currently feels abrupt.'}
};
function updateURL(){const p=new URLSearchParams({screen,variant,lang:language,mode,state:scenario});if(large)p.set('text','large');history.replaceState(null,'',`${location.pathname}?${p}`)}
function render(){updateURL();document.documentElement.lang=language;const c=concepts(),n=names();document.getElementById('study').innerHTML=`<header class="study-header"><div class="brand"><img src="assets/bun.svg" alt=""><div><strong>Bun Do</strong><span>${t('Clearer everyday screens · Design study 01','Selkeämmät arjen näkymät · Suunnittelututkielma 01')}</span></div></div><p>${t('Interactive browser proposals, not the Android app. Sample data only. Nothing is sent or saved.','Selainluonnoksia, ei Android-sovellus. Vain esimerkkitietoja. Mitään ei lähetetä tai tallenneta.')}</p></header><div class="study-layout"><label class="mobile-screen-select">${t('Screen','Näkymä')}<select id="mobile-screen">${validScreens.map(k=>`<option value="${k}" ${k===screen?'selected':''}>${n[k]}</option>`).join('')}</select></label><nav class="sidebar" aria-label="${t('Study screens','Esikatseltavat näkymät')}"><h2>${t('First batch','Ensimmäinen erä')}</h2>${validScreens.map((k,i)=>`${i===7?'<div class="separator"></div>':''}<button class="screen-link" data-screen="${k}" ${k===screen?'aria-current="page"':''}>${icon(k==='family'?'home':k)}${n[k]}</button>`).join('')}<p class="sidebar-note">${t('Same paper, evergreen, system type and approved artwork. We are comparing structure, not new branding.','Sama paperi, vihreä, järjestelmäfontti ja hyväksytyt kuvat. Vertailemme rakennetta, emme uutta brändiä.')}</p></nav><main class="workspace"><div class="workspace-heading"><div><h1>${n[screen]}</h1><p class="lead">${findings[screen]?t(...findings[screen]):screen==='audit'?t('What needs work, what should stay, and what the evidence covers.','Mitä muutetaan, mitä säilytetään ja mitä on tarkistettu.'):t('Fix the repeated pattern once, then use it everywhere.','Korjaa toistuva rakenne kerran ja käytä sitä kaikkialla.')}</p></div></div><div class="toolbar"><label>${t('Preview language','Esikatselun kieli')}<select id="language"><option value="fi" ${language==='fi'?'selected':''}>Suomi</option><option value="en" ${language==='en'?'selected':''}>English</option></select></label>${findings[screen]?`<label>${t('Demo state','Esimerkkitila')}<select id="scenario"><option value="normal" ${scenario==='normal'?'selected':''}>${t('Default','Oletus')}</option><option value="offline" ${scenario==='offline'?'selected':''}>${t('Offline','Ei verkkoyhteyttä')}</option><option value="error" ${scenario==='error'?'selected':''}>${t('Request failed','Pyyntö epäonnistui')}</option></select></label><label>${t('Text size','Tekstin koko')}<select id="text-size"><option value="normal">${t('Normal','Normaali')}</option><option value="large" ${large?'selected':''}>${t('Large','Suuri')}</option></select></label><span class="spacer"></span><button class="tool-button compare-control" id="compare">${mode==='compare'?t('Focus one option','Näytä yksi vaihtoehto'):t('Compare all three','Vertaa kaikkia kolmea')}</button><button class="tool-button" id="reset">${t('Reset demo','Aloita alusta')}</button>`:''}<button class="tool-button" id="copy-link">${t('Copy this view’s link','Kopioi näkymän linkki')}</button></div>${findings[screen]?`<div class="comparison ${mode==='focus'?'focus':''}">${(mode==='focus'?[variant]:['A','B','C']).map(v=>`<section class="variant-column ${v!==variant?'mobile-hidden':''}" data-variant="${v}" aria-label="${v}: ${c[v].title}"><div class="variant-title"><span class="variant-letter">${v}</span><h2>${c[v].title}</h2></div><p class="variant-description">${c[v].body}</p><div class="phone ${large?'large':''}" lang="${language}"><div class="phone-scroll">${renderPhone(v)}</div></div><div class="comparison-notes"><p lang="en"><strong>Trade-off</strong> ${tradeoffs[screen][v]}</p></div><p class="state-code">${t('Demo state','Esimerkkitila')}: ${esc(JSON.stringify({connection:scenario,step:memory[v].step||1,view:memory[v].aux?'details':memory[v].page||'start',...memory[v].lastChange}))}</p></section>`).join('')}</div>`:screen==='audit'?audit():components()}<p class="study-footer">${t('All actions are simulated. Switching screens resets the demo. Finnish and English copy are proposals. Browser text scaling is not Android accessibility verification.','Kaikki toiminnot ovat simuloituja. Näkymän vaihtaminen nollaa esimerkin. Suomen- ja englanninkieliset tekstit ovat ehdotuksia. Selaimen tekstikoko ei vastaa Androidin saavutettavuustestausta.')}</p></main></div>${findings[screen]?`<div class="switcher" aria-label="${t('Compare design options','Vertaile vaihtoehtoja')}"><button id="prev" aria-label="${t('Previous option','Edellinen vaihtoehto')}">${icon('arrow')}</button><div class="label">${variant} · ${c[variant].title}<small>${t('Arrow keys also switch options','Vaihda myös nuolinäppäimillä')}</small></div><button id="next" aria-label="${t('Next option','Seuraava vaihtoehto')}">${icon('chevron')}</button></div>`:''}`;bind()}
function announce(text){document.getElementById('announcement').textContent=text}
function navigate(next){screen=next;memory={A:{},B:{},C:{}};render();window.scrollTo(0,0)}
function changeVariant(dir){variant=['A','B','C'][(['A','B','C'].indexOf(variant)+dir+3)%3];render();announce(variant+' '+concepts()[variant].title)}
function show(s,title,body,confirm){s.aux=true;s.auxTitle=title;s.auxBody=body;s.confirm=confirm;s.message=''}
function simulate(s,text){s.message=t('Demo only. ','Vain esikatselu. ')+text;s.lastChange={action:'simulated'};announce(s.message)}
function action(a,v='B'){
 const s=memory[v];const focusAction=document.activeElement?.dataset?.action; if(a.startsWith('nav:')){navigate(a.slice(4));return}
 s.message='';const [key,value]=a.split(':');
 switch(key){
 case 'page':s.previousPage=s.page;s.page=value;break;
 case 'back':s.page=s.previousPage;s.previousPage=undefined;s.step=1;break;
 case 'close-aux':s.aux=false;s.confirm=null;break;
 case 'home':show(s,t('Family tasks','Perheen tehtävät'),`<h2>${t('Back to everyday tasks','Takaisin arjen tehtäviin')}</h2><p>${t('In the app, Back returns to the previous screen. This study focuses on setup and empty states. Use the study navigation to compare another screen.','Sovelluksessa Takaisin palauttaa edelliselle sivulle. Tässä esikatselussa keskitytään asetuksiin ja tyhjiin näkymiin. Vertaa muita sivuja esikatselun valikosta.')}</p>`);break;
 case 'step':s.step=Number(value);break;
 case 'toggle':s[value]=!(s[value]??(['analysis','motion','garden'].includes(value)||value.startsWith('include')));s.lastChange={[value]:s[value]};if(s.aux&&['motion','garden'].includes(value)){s.auxBody=`${row(t('App language','Sovelluksen kieli'),t('English','Suomi'),'language','language-choice')}${toggle(t('Small action animations','Pienet toimintoanimaatiot'),'', 'motion',s.motion!==false)}${toggle(t('Bun garden','Bunin puutarha'),'', 'garden',s.garden!==false)}`;}break;
 case 'local':s.local=value==='true';s.lastChange={localSpeech:s.local};break;
 case 'voice-mode':show(s,t('Speech to text','Puhe tekstiksi'),`<h2>${t('Choose speech mode','Valitse puheentunnistus')}</h2>${choice(t('Automatic','Automaattinen'),t('Online audio goes to Microsoft Azure. Offline speech uses installed Parakeet.','Verkossa ääni lähetetään Microsoft Azureen. Offline-sanelu käyttää asennettua Parakeetia.'),'choose-local:false',!s.local)}${choice(t('On this phone','Tällä puhelimella'),t('Audio stays here. Download required.','Ääni pysyy täällä. Vaatii latauksen.'),'choose-local:true',s.local)}`);break;
 case 'choose-local':s.local=value==='true';s.aux=false;s.lastChange={localSpeech:s.local};break;
 case 'install':s.installed=true;simulate(s,t('No model was downloaded. Offline speech is now shown as ready.','Mallia ei ladattu. Offline-sanelu näytetään nyt valmiina.'));break;
 case 'voice-finish':s.step=1;simulate(s,t('Voice preferences applied to this preview.','Puheasetukset otettu käyttöön tässä esikatselussa.'));break;
 case 'voice-history':show(s,t('Drafts and recordings','Luonnokset ja tallenteet'),`<h2>${t('Nothing saved here yet','Ei vielä tallenteita')}</h2><p>${t('Unfinished voice drafts appear here. Audio is only kept when you choose to keep recordings.','Keskeneräiset puheluonnokset näkyvät täällä. Ääni säilytetään vain, jos otat tallenteiden säilyttämisen käyttöön.')}</p>`);break;
 case 'language-choice':show(s,t('App language','Sovelluksen kieli'),`<h2>${t('App language','Sovelluksen kieli')}</h2><p class="hint">${t('Your tasks keep their original language.','Tehtävien alkuperäinen kieli säilyy.')}</p>${['system','fi','en'].map(k=>choice(k==='system'?t('Use device language','Laitteen kieli'):k==='fi'?'Suomi':'English','',`pref-lang:${k}`,(s.prefLang||'system')===k)).join('')}`);break;
 case 'pref-lang':s.prefLang=value;s.aux=false;s.lastChange={appLanguage:value};simulate(s,t('App language selected. The study language is controlled above.','Sovelluksen kieli valittu. Esikatselun kieli valitaan yläpuolelta.'));break;
 case 'settings-appearance':show(s,t('Appearance','Ulkoasu'),`${row(t('App language','Sovelluksen kieli'),t('English','Suomi'),'language','language-choice')}${toggle(t('Small action animations','Pienet toimintoanimaatiot'),'', 'motion',s.motion!==false)}${toggle(t('Bun garden','Bunin puutarha'),'', 'garden',s.garden!==false)}`);break;
 case 'family':s.familyChoice=value;break;
 case 'family-continue':s.page=s.familyChoice||'create';break;
 case 'local-tasks':simulate(s,t('Would return to your local task list. Family setup remains available in Settings.','Palaisi paikalliseen tehtävälistaan. Perheen käyttöönotto löytyy edelleen asetuksista.'));break;
 case 'mock-signin':simulate(s,t('Would open Microsoft sign-in. No account or family is changed.','Avaisi Microsoft-kirjautumisen. Tiliä tai perhettä ei muuteta.'));break;
 case 'members':show(s,t('Family members','Perheen jäsenet'),`<h2>${t('Our home','Meidän koti')}</h2><p class="hint">${t('Example household','Esimerkkiperhe')}</p><div class="review-item">${t('You · Owner','Sinä · Omistaja')}</div><div class="review-item">${t('Other family member','Toinen perheenjäsen')}</div>${btn(t('Invite someone','Kutsu mukaan'),'invite','primary','plus')}<p class="hint">${t('Member removal and ownership changes keep their existing confirmations.','Jäsenen poistaminen ja omistajan vaihtaminen säilyttävät nykyiset vahvistuksensa.')}</p>`);break;
 case 'invite':show(s,t('Invite someone','Kutsu mukaan'),`<h2>${t('Share a family invitation','Jaa perheen kutsu')}</h2><p>${t('The link is for one person and expires in 24 hours. Check their code before approving them.','Linkki on yhdelle henkilölle ja vanhenee 24 tunnissa. Tarkista hänen koodinsa ennen hyväksymistä.')}</p>`,{label:t('Create invitation','Luo kutsu')});break;
 case 'switch-account':show(s,t('Use another account','Käytä toista tiliä'),`<h2>${t('Check your saved work first','Tarkista tallennetut työt ensin')}</h2><p>${t('Saved local work stays with this account. You will need to sign back into the same account to open it. Export a copy first if you need one.','Tallennetut paikalliset työt pysyvät tällä tilillä. Niiden avaaminen vaatii kirjautumisen samalle tilille. Vie tarvittaessa ensin kopio.')}</p>${btn(t('Review saved work','Tarkista tallennetut työt'),'nav:recovery','secondary')}`,{label:t('Continue to sign-in','Jatka kirjautumiseen')});break;
 case 'signout':show(s,t('Sign out?','Kirjaudutaanko ulos?'),`<h2>${t('Your saved work stays here','Tallennetut työsi säilyvät täällä')}</h2><p>${t('It will be locked to this account. Sign in with the same account to open it again. Export a copy first if you need one.','Työt lukitaan tälle tilille. Avaa ne kirjautumalla samalla tilillä. Vie tarvittaessa ensin kopio.')}</p>${btn(t('Review saved work','Tarkista tallennetut työt'),'nav:recovery','secondary')}`,{label:t('Sign out','Kirjaudu ulos')});break;
 case 'delete-local':show(s,t('Delete local data?','Poistetaanko paikalliset tiedot?'),`<h2>${t('Delete this account’s data from this phone?','Poistetaanko tämän tilin tiedot puhelimelta?')}</h2><p>${t('This permanently deletes local tasks, drafts and retained recordings, then signs you out. Export anything you need first. Shared household tasks are not deleted.','Tämä poistaa pysyvästi paikalliset tehtävät, luonnokset ja säilytetyt äänitteet sekä kirjaa ulos. Vie ensin tarvitsemasi tiedot. Perheen yhteisiä tehtäviä ei poisteta.')}</p>${btn(t('Review saved work','Tarkista tallennetut työt'),'nav:recovery','secondary')}`,{label:t('Delete local data and sign out','Poista paikalliset tiedot ja kirjaudu ulos'),danger:true});break;
 case 'confirm-demo':s.aux=false;s.confirm=null;simulate(s,t('No data, account, or invitation was changed.','Tietoja, tiliä tai kutsuja ei muutettu.'));break;
 case 'check-connection':show(s,t('Connection','Yhteys'),`<h2>${offline()?t('You are offline','Ei verkkoyhteyttä'):scenario==='error'?t('Could not connect','Yhteyttä ei saatu'):t('Connected','Yhteys toimii')}</h2><p>${offline()?t('Reconnect and try again. Your saved work stays on this phone.','Yhdistä verkkoon ja yritä uudelleen. Tallennetut työt säilyvät tällä puhelimella.'):t('This is a simulated connection check, not a request to the Bun Do backend.','Tämä on simuloitu yhteystarkistus, ei pyyntö Bun Don palvelimelle.')}</p>`);break;
 case 'reminders':show(s,t('Reminders','Muistutukset'),`<h2>${t('Which tasks should remind you?','Mistä tehtävistä muistutetaan?')}</h2>${choice(t('Off','Pois'),'', 'reminder:off',(s.reminder||'off')==='off')}${choice(t('Mine and unclaimed','Omat ja varaamattomat'),'', 'reminder:mine',s.reminder==='mine')}${choice(t('All family tasks','Kaikki perheen tehtävät'),'', 'reminder:all',s.reminder==='all')}${field(t('When no time is set','Kun aikaa ei ole asetettu'),'reminderTime','09:00','','time')}<p class="hint">${t('Android may delay reminders. Another device may also remind you.','Android voi viivästyttää muistutuksia. Myös toinen laite voi muistuttaa.')}</p>`);break;
 case 'reminder':s.reminder=value;s.aux=false;simulate(s,t('Reminder choice updated for this demo.','Muistutusvalinta päivitetty esikatseluun.'));break;
 case 'import':show(s,t('Import a recovery file','Tuo palautustiedosto'),`<h2>${t('Choose a Bun Do recovery file','Valitse Bun Don palautustiedosto')}</h2><p>${t('In Android, this opens the file picker. This preview uses two sample tasks instead, then lets you review them.','Androidissa tämä avaa tiedostovalitsimen. Esikatselu näyttää sen sijaan kaksi esimerkkitehtävää tarkistettavaksi.')}</p>${btn(t('Preview sample file','Esikatsele esimerkkitiedosto'),'sample-file')}`);break;
 case 'sample-file':s.aux=false;s.page='review';break;
 case 'export-json':case 'export-text':simulate(s,t('Would open the Android save picker. No file has been written.','Avaisi Androidin tallennusvalitsimen. Tiedostoa ei kirjoitettu.'));break;
 case 'copy-selected':simulate(s,t('Selected tasks copied to the demo’s local inbox. Nothing was shared.','Valitut tehtävät kopioitu esimerkin paikalliseen listaan. Mitään ei jaettu.'));break;
 case 'adventure-choice':s.adventureChoice=value;break;
 case 'adventure-next':if(s.adventureChoice==='existing')s.page='queue';else{navigate('planner');return}break;
 case 'retry-adventures':s.page='suggestion';simulate(s,t('Showing a sample successful response.','Näytetään esimerkki onnistuneesta vastauksesta.'));break;
 case 'add-task':if(!s.task?.trim()){simulate(s,t('Enter a task title first.','Kirjoita ensin tehtävän nimi.'));break}simulate(s,t('Task added to this preview only.','Tehtävä lisätty vain esikatseluun.'));break;
 case 'start-adventure':simulate(s,t('The adventure would start for the whole family. Tasks stay unclaimed.','Seikkailu alkaisi koko perheelle. Tehtäviä ei varata kenellekään.'));break;
 case 'demo-record':show(s,t('Voice preview','Puheen esikatselu'),`<h2>${t('Try a sample recording','Kokeile esimerkkisanelua')}</h2><p>${t('This study does not use your microphone. Use a sample transcript to try the next step.','Esikatselu ei käytä mikrofonia. Kokeile seuraavaa vaihetta esimerkkitekstillä.')}</p>${btn(t('Use sample transcript','Käytä esimerkkitekstiä'),'use-transcript','primary','voice')}`);break;
 case 'use-transcript':s.aux=false;s.goal=t('Get the kitchen ready for the weekend','Keittiö kuntoon viikonlopuksi');s.task=s.goal;s.lastChange={sampleTranscript:true};break;
 case 'ideas':s.ideas=true;s.lastChange={sampleIdeas:true};break;
 case 'idea':s.goal=t(['A calmer kitchen','Make room in the hallway','Get ready for the weekend'][Number(value)],['Keittiö kuntoon','Eteiseen lisää tilaa','Valmistaudu viikonloppuun'][Number(value)]);break;
 case 'minutes':s.minutes=value;break;
 case 'planner-next':s.step=2;break;
 case 'generate':if(!s.goal?.trim()||offline()||!validMinutes(s))break;s.page='review';break;
 case 'approve-plan':if([0,1,2].every(i=>s['include'+i]===false)){simulate(s,t('Keep at least one task.','Säilytä vähintään yksi tehtävä.'));break}simulate(s,t('Approved tasks would be added first. The shared adventure starts after they sync. No real tasks were created.','Hyväksytyt tehtävät lisättäisiin ensin. Seikkailu alkaa synkronoinnin jälkeen. Oikeita tehtäviä ei luotu.'));break;
 default:simulate(s,t('This action is not part of the first preview batch.','Tämä toiminto ei kuulu ensimmäiseen esikatseluerään.'));
 }
 const scrolls=[...document.querySelectorAll('.variant-column')].map(el=>[el.dataset.variant,el.querySelector('.phone-scroll')?.scrollTop||0]);render();
 const focusTarget=focusAction&&[...document.querySelectorAll(`[data-variant="${v}"] [data-action]`)].find(e=>e.dataset.action===focusAction);if(focusTarget)focusTarget.focus({preventScroll:true});else{const heading=document.querySelector(`[data-variant="${v}"] .content h2`);if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}}
 if(['toggle','minutes','local','pref-lang','idea','adventure-choice','family','install'].includes(key))for(const [id,top]of scrolls){const el=document.querySelector(`[data-variant="${id}"] .phone-scroll`);if(el)el.scrollTop=top}
}
function bind(){
 document.getElementById('mobile-screen').onchange=e=>navigate(e.target.value);
 document.querySelectorAll('[data-screen]').forEach(el=>el.onclick=()=>navigate(el.dataset.screen));
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el.closest('[data-variant]')?.dataset.variant||variant));
 document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{const v=el.closest('[data-variant]').dataset.variant,s=memory[v];s[el.dataset.field]=el.value;const area=el.closest('.phone-scroll');area.querySelectorAll('[data-generate]').forEach(b=>b.disabled=offline()||!s.goal?.trim()||!validMinutes(s));area.querySelectorAll('[data-continue]').forEach(b=>b.disabled=!s.goal?.trim())});
 document.querySelectorAll('[data-item]').forEach(el=>el.onchange=()=>{const s=memory[el.closest('[data-variant]').dataset.variant],i=Number(el.dataset.item);s.excluded=(s.excluded||[]).filter(x=>x!==i);if(!el.checked)s.excluded.push(i);el.closest('.phone-scroll').querySelector('[data-action="copy-selected"]').disabled=s.excluded.length===2});
 document.getElementById('language').onchange=e=>{language=e.target.value;memory={A:{},B:{},C:{}};render()};
 const scenarioEl=document.getElementById('scenario');if(scenarioEl)scenarioEl.onchange=e=>{scenario=e.target.value;memory={A:{},B:{},C:{}};render()};
 const textEl=document.getElementById('text-size');if(textEl)textEl.onchange=e=>{large=e.target.value==='large';render()};
 const compare=document.getElementById('compare');if(compare)compare.onclick=()=>{mode=mode==='compare'?'focus':'compare';render()};
 const reset=document.getElementById('reset');if(reset)reset.onclick=()=>{memory={A:{},B:{},C:{}};render()};
 const prev=document.getElementById('prev'),next=document.getElementById('next');if(prev)prev.onclick=()=>changeVariant(-1);if(next)next.onclick=()=>changeVariant(1);
 document.getElementById('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);document.getElementById('copy-link').textContent=t('Link copied','Linkki kopioitu')}catch{document.getElementById('copy-link').textContent=t('Copy the address bar URL','Kopioi osoite osoiteriviltä')}};
}
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.target.closest('input,textarea,select,[contenteditable="true"],[role="slider"]'))return;if(findings[screen]&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeVariant(e.key==='ArrowLeft'?-1:1)}});
render();
